@php
    $normalizePhone = function (?string $phone): string {
        $phone = preg_replace('/\D+/', '', (string) $phone) ?? '';
        return str_starts_with($phone, '0') ? '62' . substr($phone, 1) : $phone;
    };
    $hasFilter = $search !== '' || $filter !== 'all';
